-- AD9 CHECK (read-only): one row per rule, ok must be true on every row. Run through ad-sql-run.sh after AD9.sql.
SELECT 'nine runbooks, each with a current version' AS rule, (SELECT count(*) FROM desk.fadm_runbook) >= 9 AND (SELECT count(DISTINCT runbook_key) FROM desk.fadm_runbook_version) >= 9 AS ok
UNION ALL SELECT 'every version has exactly six parts and the fixed no-promise line (CHECKs exist)', (SELECT count(*) FROM pg_constraint WHERE conrelid='desk.fadm_runbook_version'::regclass AND conname IN ('runbook_six_parts','runbook_never_line','runbook_steps','runbook_say_clean')) = 4
UNION ALL SELECT 'no stored say-text contains a promise word', NOT EXISTS (SELECT 1 FROM desk.fadm_runbook_version WHERE NOT desk.fadm_runbook_clean(say_text) OR NOT desk.fadm_runbook_clean(parts->>'say'))
UNION ALL SELECT 'the three tables have forced RLS and desk_app has no right on them', (SELECT bool_and(relrowsecurity AND relforcerowsecurity) FROM pg_class WHERE oid IN ('desk.fadm_runbook'::regclass,'desk.fadm_runbook_version'::regclass,'desk.fadm_runbook_event'::regclass)) AND NOT has_table_privilege('desk_app','desk.fadm_runbook','select') AND NOT has_table_privilege('desk_app','desk.fadm_runbook_version','select') AND NOT has_table_privilege('desk_app','desk.fadm_runbook_event','insert')
UNION ALL SELECT 'versions and events are append-only (frozen triggers)', (SELECT count(*) FROM pg_trigger WHERE tgrelid IN ('desk.fadm_runbook_version'::regclass,'desk.fadm_runbook_event'::regclass) AND tgname LIKE '%frozen%') = 4
UNION ALL SELECT 'the four doors are granted to desk_app and are SECURITY DEFINER', has_function_privilege('desk_app','desk.fadm_runbooks_list(uuid)','execute') AND has_function_privilege('desk_app','desk.fadm_runbook_add_version(uuid,text,int,int,int,jsonb,jsonb,text,text)','execute') AND has_function_privilege('desk_app','desk.fadm_runbook_mark(uuid,bigint,text)','execute') AND has_function_privilege('desk_app','desk.fadm_runbook_chain_verify()','execute') AND (SELECT bool_and(prosecdef) FROM pg_proc WHERE proname IN ('fadm_runbooks_list','fadm_runbook_add_version','fadm_runbook_mark','fadm_runbook_chain_verify'))
UNION ALL SELECT 'the internal helper is not callable by desk_app or PUBLIC', NOT has_function_privilege('desk_app','desk.fadm_runbook_staff(uuid)','execute') AND NOT has_function_privilege('public','desk.fadm_runbook_staff(uuid)','execute')
UNION ALL SELECT 'the four runbook ledger kinds are on the closed list', (SELECT count(*) FROM desk.fadm_ledger_kind WHERE kind IN ('ad9.selftest','runbook.version_added','runbook.approved','runbook.validated')) = 4
UNION ALL SELECT 'the version hash chain verifies', desk.fadm_runbook_chain_verify()
UNION ALL SELECT 'the main ledger hash chain still verifies', desk.fadm_ledger_verify();
